#include <stdio.h>
#include <sys/param.h>

#define distance(x,y)   (((x)<(y))?((y)-(x)):((x)-(y)))

#define SNEDEBUG 1

// seqnoからSNEを計算する、単体で動作するコアのコード
// >> 代替実装をテストするには、この関数を独自のコードに置き換える
unsigned long compute_sne(unsigned long seqno) {
    // 入力: 32ビット符号なしシーケンス番号（下位ビット）
    // 出力: 32ビット符号なしSNE（上位ビット）

    // このコード例でSNEの計算に使用する変数:

    static unsigned long
      RCV_SNE = 0;        // SNEの最高到達値
    static int
      RCV_SNE_FLAG = 1;   // ロールオーバー後の前半でセットされる
                          // （再度のロールオーバーを防ぐ）
    static unsigned long
      RCV_PREV_SEQ = 0;   // SEQの最高到達値
    unsigned long
      holdSNE;            // 出力の一時コピー

    holdSNE = RCV_SNE;                // まず現在のSNEを使う
    if (distance(seqno,RCV_PREV_SEQ) < 0x80000000) {
        // 両方とも同じSNE範囲内か？
        if ((seqno >= 0x80000000) && (RCV_PREV_SEQ < 0x80000000)) {
            // N/2を越えて前方にジャンプしたか？
            RCV_SNE_FLAG = 0;         // ラップ増加フラグをリセット
        }
        RCV_PREV_SEQ = MAX(seqno,RCV_PREV_SEQ);
                                      // 必要ならprevを前方に進める
    } else {
            // 両者は異なるSNE範囲にある
            if (seqno < 0x80000000) {
                // ゼロを越えて前方にジャンプしたか？
                RCV_PREV_SEQ = seqno; // prevを更新
                if (RCV_SNE_FLAG == 0) {
                    // 初めてゼロを越えたか？（ラップ）
                    RCV_SNE_FLAG = 1;
                              // 1回だけ増やすようにフラグをセット
                    RCV_SNE = RCV_SNE + 1;
                              // ウィンドウを1つ進める
                    holdSNE = RCV_SNE;
                              // 更新後のSNE値を使う
                }
            } else {
                // ゼロを越えて後方にジャンプ
                holdSNE = RCV_SNE - 1;
                              // ロールオーバー前のSNE値を使う
            }
    }
    #ifdef SNEDEBUG
    fprintf(stderr,"state RCV_SNE_FLAG =        %1d\n",
      RCV_SNE_FLAG);
    fprintf(stderr,"state      RCV_SNE = %08lx\n", RCV_SNE);
    fprintf(stderr,"state RCV_PREV_SEQ = %08lx\n", RCV_PREV_SEQ);
    #endif
    return holdSNE;
}

int main() {
    // 入力および出力として使用する変数:
    unsigned long SEG_SEQ;        // 入力 - 受信したSEQ
    unsigned long SNE;            // 出力 - 受信したSEQに
                                  // 対応するSNE

    // 計算したSNEを検証するために使用する変数:
    unsigned long SEG_HIGH;       // 入力 - 送信側のSNE
                                  // -> SNEはこの値と一致するはず
    unsigned long long BIG_PREV;  // 前回の64ビット全体のseqno
    unsigned long long BIG_THIS = 0;  // 現在の64ビット全体のseqno
                                  // -> THISとPREVの差が
                                  //    SEQ空間の半分を超えることはない

   char *prompt = "Input hex numbers only (0x is optional)\n\n")
                  "\tHex input\n"
                  "\t(2 hex numbers separated by whitespace,"
                  "each with 8 or fewer digits)";

    fprintf(stderr,"%s\n",prompt);

    while (scanf("%lx %lx",&SEG_HIGH,&SEG_SEQ) == 2) {
        BIG_PREV = BIG_THIS;
        BIG_THIS = (((unsigned long long)SEG_HIGH) << 32)
                  | ((unsigned long long)SEG_SEQ);

        // SEG_SEQからSNEを計算する
        SNE = compute_sne(SEG_SEQ);

        fprintf(stderr,"           SEG_SEQ = %08lx\n", SEG_SEQ);
        fprintf(stderr,"               SNE = %08lx\n", SNE);
        fprintf(stderr,"          SEG_HIGH = %08lx %s\n",SEG_HIGH,
                (SEG_HIGH == SNE)? " - OK" : " - ERROR !!!!!!!");
        fprintf(stderr,"\t\tthe jump was %16llx %s %s\n",
                distance(BIG_PREV,BIG_THIS),
                ((BIG_PREV < BIG_THIS)?"+":"-"),
                (((distance(BIG_PREV,BIG_THIS)) > 0x7FFFFFFF)
                 ? "ILLEGAL JUMP" : "."));
        fprintf(stderr,"\n");
        fprintf(stderr,"\n");

        fprintf(stderr,"%s\n",prompt);

    }
}
